const e=JSON.parse('[{"id":"upsc-2018-prelims-csat-a-041","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":41,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A student has to get 40% marks to pass in an examination. Suppose he gets 30 marks and fails by 30 marks, then what are the maximum marks in the examination?","options":{"a":"100","b":"120","c":"150","d":"300"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"A student has to get 40% marks to pass in an examination. Suppose he gets 30 marks and fails by 30 marks, then what are the maximum marks in the examination?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passing mark is 30+30=60, which is 40% of the maximum. Maximum marks are 60/0.40=150.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-042","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":42,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"19 boys turn out for playing hockey. Of these, 11 are wearing hockey shirts and 14 are wearing hockey pants. There are no boys without shirts and/ or pants. What is the number of boys wearing full uniform?","options":{"a":"3","b":"5","c":"6","d":"8"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"19 boys turn out for playing hockey. Of these, 11 are wearing hockey shirts and 14 are wearing hockey pants. There are no boys without shirts and/ or pants. What is the number of boys wearing full uniform?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"By inclusion-exclusion, boys with both shirt and pants number 11+14−19=6.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-043","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":43,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A is studying in","options":{"a":"Rajasthan","b":"Gujarat","c":"City Q","d":"Kerala"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":21,"blocks":[{"type":"passage","text":"A, B, C and D are students. They are studying in four different cities, viz., P, Q, R and S (not necessarily in that order). They are studying in Science college, Arts college, Commerce college and Engineering college (not necessarily in that order), which are situated in four different States, viz., Gujarat, Rajasthan, Assam and Kerala (not necessarily in that order). Further, it is given that\\ni. D is studying in Assam\\nii. Arts college is located in city S which is in Rajasthan\\niii. A is studying in Commerce college\\niv. B is studying in city Q\\nv. Science college is located in Kerala"},{"type":"paragraph","text":"A is studying in"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"D is in Assam, Science is in Kerala and Arts is in Rajasthan. A’s Commerce college must be in the remaining State, Gujarat.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-044","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":44,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Science college is located in","options":{"a":"city Q","b":"city S","c":"city R","d":"city P"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=23","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":23,"blocks":[{"type":"passage","text":"A, B, C and D are students. They are studying in four different cities, viz., P, Q, R and S (not necessarily in that order). They are studying in Science college, Arts college, Commerce college and Engineering college (not necessarily in that order), which are situated in four different States, viz., Gujarat, Rajasthan, Assam and Kerala (not necessarily in that order). Further, it is given that\\ni. D is studying in Assam\\nii. Arts college is located in city S which is in Rajasthan\\niii. A is studying in Commerce college\\niv. B is studying in city Q\\nv. Science college is located in Kerala"},{"type":"paragraph","text":"Science college is located in"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"B is in Q. B cannot study Commerce (A), Engineering (D in Assam), or Arts (in S), so B attends Science college in Q.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-045","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":45,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"C is studying in","options":{"a":"Science college","b":"Rajasthan","c":"Gujarat","d":"city Q"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=23","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":23,"blocks":[{"type":"passage","text":"A, B, C and D are students. They are studying in four different cities, viz., P, Q, R and S (not necessarily in that order). They are studying in Science college, Arts college, Commerce college and Engineering college (not necessarily in that order), which are situated in four different States, viz., Gujarat, Rajasthan, Assam and Kerala (not necessarily in that order). Further, it is given that\\ni. D is studying in Assam\\nii. Arts college is located in city S which is in Rajasthan\\niii. A is studying in Commerce college\\niv. B is studying in city Q\\nv. Science college is located in Kerala"},{"type":"paragraph","text":"C is studying in"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"A takes Commerce, B Science and D Engineering, leaving Arts in Rajasthan for C.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-046","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":46,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Which one of the following statements is correct?","options":{"a":"D is not studying in city S.","b":"A is studying in Science college.","c":"A is studying in Kerala.","d":"Engineering college is located in Gujarat."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=23","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":23,"blocks":[{"type":"passage","text":"A, B, C and D are students. They are studying in four different cities, viz., P, Q, R and S (not necessarily in that order). They are studying in Science college, Arts college, Commerce college and Engineering college (not necessarily in that order), which are situated in four different States, viz., Gujarat, Rajasthan, Assam and Kerala (not necessarily in that order). Further, it is given that\\ni. D is studying in Assam\\nii. Arts college is located in city S which is in Rajasthan\\niii. A is studying in Commerce college\\niv. B is studying in city Q\\nv. Science college is located in Kerala"},{"type":"paragraph","text":"Which one of the following statements is correct?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"D studies in Assam, whereas city S is in Rajasthan. D is therefore not studying in S.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-047","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":47,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Which one of the following statements is correct regarding Engineering college?","options":{"a":"C is studying there.","b":"B is studying there.","c":"It is located in Gujarat.","d":"D is studying there."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=23","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":23,"blocks":[{"type":"passage","text":"A, B, C and D are students. They are studying in four different cities, viz., P, Q, R and S (not necessarily in that order). They are studying in Science college, Arts college, Commerce college and Engineering college (not necessarily in that order), which are situated in four different States, viz., Gujarat, Rajasthan, Assam and Kerala (not necessarily in that order). Further, it is given that\\ni. D is studying in Assam\\nii. Arts college is located in city S which is in Rajasthan\\niii. A is studying in Commerce college\\niv. B is studying in city Q\\nv. Science college is located in Kerala"},{"type":"paragraph","text":"Which one of the following statements is correct regarding Engineering college?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"D’s Assam college cannot be Science in Kerala, Arts in Rajasthan or A’s Commerce. It is Engineering.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-048","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":48,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Which one of the following statements is correct?","options":{"a":"Engineering college is located in Assam.","b":"City Q is situated in Assam.","c":"C is studying in Kerala.","d":"B is studying in Gujarat."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=23","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":23,"blocks":[{"type":"passage","text":"A, B, C and D are students. They are studying in four different cities, viz., P, Q, R and S (not necessarily in that order). They are studying in Science college, Arts college, Commerce college and Engineering college (not necessarily in that order), which are situated in four different States, viz., Gujarat, Rajasthan, Assam and Kerala (not necessarily in that order). Further, it is given that\\ni. D is studying in Assam\\nii. Arts college is located in city S which is in Rajasthan\\niii. A is studying in Commerce college\\niv. B is studying in city Q\\nv. Science college is located in Kerala"},{"type":"paragraph","text":"Which one of the following statements is correct?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The preceding assignments put Engineering college in Assam, making A correct.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-049","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":49,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made:\\n\\n1. Climate change is not a challenge for developed countries.\\n2. Climate change is a complex policy issue and also a development issue for many countries.\\n3. Ways and means of finance must be found to enable developing countries to enhance their adaptive capacity.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=23","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":23,"blocks":[{"type":"passage","text":"All actions to address climate change ultimately involve costs. Funding is vital in order for countries like India to design and implement adaptation and mitigation plans and projects. The problem is more severe for developing countries like India, which would be one of the hardest hit by climate change, given its need to finance development. Most countries do indeed treat climate change as real threat and are striving to address it in a more comprehensive and integrated manner with the limited resources at their disposal."},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made:"},{"type":"paragraph","text":"1. Climate change is not a challenge for developed countries.\\n2. Climate change is a complex policy issue and also a development issue for many countries.\\n3. Ways and means of finance must be found to enable developing countries to enhance their adaptive capacity."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage treats climate policy as a development challenge and stresses financing adaptation. Statements 2 and 3 follow; statement 1 incorrectly excludes developed countries.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-050","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":50,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most crucial and logical inference that can be made from the above passage?","options":{"a":"Rural people are giving up the use of polluting solid fuels due to their increasing awareness of health hazards.","b":"Subsidizing the use of clean cooking fuels will solve the problem of India’s indoor air pollution.","c":"India should increase its import of natural gas and produce more electricity.","d":"Access to cooking gas can reduce premature deaths in poor households."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=25","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":25,"blocks":[{"type":"passage","text":"Cooking with biomass and coal in India is now recognized to cause major health problems, with women and children in poor populations facing the greatest risk. There are more than 10 lakh premature deaths each year from household air pollution due to polluting cooking fuels with another 1.5 lakh due to their contribution to general outdoor air pollution in the country. Although the fraction of the Indian population using clean cooking fuels, such as LPG, natural gas and electricity, is slowly rising, the number using polluting solid fuels as their primary cooking fuel has remained static for nearly 30 years at about 70 crore."},{"type":"paragraph","text":"Which of the following is the most crucial and logical inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Household pollution causes premature deaths and clean cooking fuels reduce exposure. Improved access to cooking gas is the supported inference.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-051","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":51,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most important implication of the passage?","options":{"a":"A happy world is a dream of science.","b":"Science only can build a happy world, but it is also the only major threat.","c":"A happy world is not possible without science.","d":"A happy world is not at all possible with or without science."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=25","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":25,"blocks":[{"type":"passage","text":"Scientific knowledge has its dangers, but so has every great thing. Over and beyond the dangers with which it threatens the present, it opens up as nothing else can, the vision of a possible happy world; a world without poverty, without war, with little illness. Science, whatever unpleasant consequences it may have by the way, is in its very nature a liberator."},{"type":"paragraph","text":"Which one of the following is the most important implication of the passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage explicitly presents science as opening the vision of a possible happy world, despite its dangers. UPSC accepts A, describing that hopeful vision.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-052","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":52,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most important implication of the passage?","options":{"a":"India can have territorial claims in the Arctic territory and free access to its resources.","b":"Melting of summer ice in the Arctic leads to changes in the geopolitics.","c":"The Arctic region will solve the world’s future problem of resource crunch.","d":"The Arctic region has more resources than Antarctica."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=25","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":25,"blocks":[{"type":"passage","text":"The Arctic’s vast reserves of fossil fuel, fish and minerals are now accessible for a longer period in a year. But unlike Antarctica, which is protected from exploitation by the Antarctic Treaty framed during the Cold War and is not subject to territorial claims by any country, there is no legal regime protecting the Arctic from industrialization, especially at a time when the world craves for more and more resources. The distinct possibility of ice-free summer has prompted countries with Arctic coastline to scramble for great chunks of the melting ocean."},{"type":"paragraph","text":"Which one of the following is the most important implication of the passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Melting ice exposes resources and prompts territorial competition among Arctic States. This changes regional geopolitics.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-053","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":53,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the crucial message conveyed by the above passage?","options":{"a":"India should revise its PDS.","b":"India should not be a member of WTO.","c":"For India food security collides with trade.","d":"India provides food security to its poor."},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=27","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":27,"blocks":[{"type":"passage","text":"Being a member of the WTO, India is bound by the agreements that have been signed and ratified by its members, including itself. According to Article 6 of the Agriculture Agreement, providing minimum support prices for agricultural products is considered distorting and is subject to limits. The subsidy arising from ‘minimal supports’ cannot exceed 10 per cent of the value of agricultural production for developing countries. PDS in India entails minimum support prices and public stockholding of food grains. It is possible that, in some years, the subsidy to producers will exceed 10 per cent of the value of agricultural production."},{"type":"paragraph","text":"What is the crucial message conveyed by the above passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage contrasts India’s food-support policies with WTO subsidy limits. The central issue is a collision between food security and trade rules.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-054","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":54,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made\\n\\n1. India continues to be a developing country essentially due to its faulty education system.\\n2. Today’s learners need to acquire new-age skill-sets.\\n3. A good number of Indians go to some developed countries for education because the educational systems there are a perfect reflection of the societies in which they function.\\n\\nWhich of the above assumptions is/ are valid?","options":{"a":"1 and 3 only","b":"2 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=27","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":27,"blocks":[{"type":"passage","text":"India’s educational system is modelled on the mass education system that developed in the 19th century in Europe and later spread around the world. The goal of the system is to condition children as ‘good’ citizens and productive workers. This suited the industrial age that needed the constant supply of a compliant workforce with a narrow set of capabilities. Our educational institutes resemble factories with bells, uniforms and batch-processing of learners, designed to get learners to conform. But, from an economic point of view, the environment today is very different. It is a complex, volatile and globally interconnected world."},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made"},{"type":"paragraph","text":"1. India continues to be a developing country essentially due to its faulty education system.\\n2. Today’s learners need to acquire new-age skill-sets.\\n3. A good number of Indians go to some developed countries for education because the educational systems there are a perfect reflection of the societies in which they function."},{"type":"paragraph","text":"Which of the above assumptions is/ are valid?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The industrial-era model is contrasted with a complex modern economy, supporting the need for new-age skills. The other assumptions add explanations or comparisons not given.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-055","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":55,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the most logical and rational inference that can be made from the above passage?","options":{"a":"Obesity has become an epidemic all over the world.","b":"A lot of people are obsessed with attaining a perfect body.","c":"Obesity is essentially an incurable disease.","d":"There is no perfect diet or one solution for obesity."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=29","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":29,"blocks":[{"type":"passage","text":"The practice of dieting has become an epidemic; everyone is looking out for a way to attain that perfect body. We are all different with respect to our ethnicity, genetics, family history, gender, age, physical and mental and spiritual health status, lifestyles and preferences. Thereby we also differ in what foods we tolerate or are sensitive to. So we really cannot reduce so many complexities into one diet or diet book. This explains the failure of diets across the world in curbing obesity. Unless the reasons for weight gain are well understood and addressed and unless habits are changed permanently, no diet is likely to succeed."},{"type":"paragraph","text":"What is the most logical and rational inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"People differ along many dimensions, and lasting weight change requires understanding causes and changing habits. A single universally successful diet is not supported.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-056","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":56,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most logical, rational and crucial message given by the passage?","options":{"a":"Preserving crop genetic diversity is an insurance against the effects of climate change.","b":"Despite great risks, monoculture is the only way to ensure food security in the world.","c":"More and more genetically modified crops only can save the world from impending shortages of food.","d":"Asia and North America will be worst sufferers from climate change and the consequent shortage of food."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=29","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":29,"blocks":[{"type":"passage","text":"Monoculture carries great risks. A single disease or pest can wipe out swathes of the world’s food production, an alarming prospect given that its growing and wealthier population will eat 70% more by 2050. The risks are magnified by the changing climate. As the planet warms and monsoon rains intensify, farmlands in Asia will flood. North America will suffer more intense droughts, and crop diseases will spread to new latitudes."},{"type":"paragraph","text":"Which of the following is the most logical, rational and crucial message given by the passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Monoculture is vulnerable to pests, disease and climate shifts. Genetic diversity spreads these risks and protects future food production.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-057","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":57,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A shopkeeper sells an article at Rs. 40 and gets X% profit. However, when he sells it at Rs. 20, he faces same percentage of loss. What is the original cost of the article?","options":{"a":"Rs. 10","b":"Rs. 20","c":"Rs. 30","d":"Rs. 40"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=29","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":29,"blocks":[{"type":"paragraph","text":"A shopkeeper sells an article at Rs. 40 and gets X% profit. However, when he sells it at Rs. 20, he faces same percentage of loss. What is the original cost of the article?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Equal profit and loss percentages mean 40−C=C−20. Hence 2C=60 and the cost is ₹30.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-058","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":58,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"There are 24 equally spaced points lying on the circumference of a circle. What is the maximum number of equilateral triangles that can be drawn by taking sets of three points as the vertices?","options":{"a":"4","b":"6","c":"8","d":"12"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=29","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":29,"blocks":[{"type":"paragraph","text":"There are 24 equally spaced points lying on the circumference of a circle. What is the maximum number of equilateral triangles that can be drawn by taking sets of three points as the vertices?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Each equilateral triangle uses points eight positions apart. The 24 points form 24/3=8 distinct such triangles.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-059","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":59,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the sequence given below :\\n\\n4/12/95, 1/1/96, 29/1/96, 26/2/96, What is the next term of the series?","options":{"a":"24/3/96","b":"25/3/96","c":"26/3/96","d":"27/3/96"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=29","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":29,"blocks":[{"type":"paragraph","text":"Consider the sequence given below :"},{"type":"paragraph","text":"4/12/95, 1/1/96, 29/1/96, 26/2/96, What is the next term of the series?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The dates advance by 28 days. In leap-year 1996, adding 28 days to 26 February gives 25 March.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-060","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":60,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Twelve equal squares are placed to fit in at rectangle of diagonal 5 cm. There are three rows containing four squares each. No gaps are left between adjacent squares. What is the area of each square?","options":{"a":"5/7 sq cm","b":"7/5 sq cm","c":"1 sq cm","d":"25/12 sq cm"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=29","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":29,"blocks":[{"type":"paragraph","text":"Twelve equal squares are placed to fit in at rectangle of diagonal 5 cm. There are three rows containing four squares each. No gaps are left between adjacent squares. What is the area of each square?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"If each square has side s, the rectangle is 4s by 3s and has diagonal 5s. The stated 5 cm diagonal gives s=1 cm and area 1 sq cm.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-061","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":61,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"Consider the following graph:\\n\\nWhich one of the following statements is not correct with reference to the graph given above?","options":{"a":"On 1st June, the actual progress of work was less than expected.","b":"The actual rate of progress of work was the greatest during the month of August.","c":"The work was actually completed before the expected time.","d":"During the period from 1st April to 1st September, at no time was the actual progress more than the expected progress."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=31","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":31,"blocks":[{"type":"paragraph","text":"Consider the following graph:"},{"type":"paragraph","text":"Which one of the following statements is not correct with reference to the graph given above?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"During August the actual-progress curve rises above the expected-progress curve. The assertion that actual progress was never greater is false.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-61.png","sourceImageAlt":"Expected and actual percentage progress of work from 1 April to 1 September."},{"id":"upsc-2018-prelims-csat-a-062","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":62,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"For a sports meet, a winners’ stand comprising three wooden blocks is in the following form There are six different colours available to choose from and each of the three wooden blocks is to be painted such that no two of them has the same colour. In how many different ways can the winners’ stand be painted?","options":{"a":"120","b":"81","c":"66","d":"36"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=31","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":31,"blocks":[{"type":"paragraph","text":"For a sports meet, a winners’ stand comprising three wooden blocks is in the following form There are six different colours available to choose from and each of the three wooden blocks is to be painted such that no two of them has the same colour. In how many different ways can the winners’ stand be painted?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The three positions receive distinct colours chosen from six: 6×5×4=120 assignments.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-62.png","sourceImageAlt":"Winners stand formed by three adjacent wooden blocks of different heights."},{"id":"upsc-2018-prelims-csat-a-063","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":63,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"Looking at the graph, it can be inferred that from 1990 to 2010","options":{"a":"population growth rate has increased","b":"population growth rate has decreased","c":"growth rate of population has remained stable","d":"population growth rate shows no trend"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=31","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":31,"blocks":[{"type":"passage","text":"The graph gives the birth rate and death rate per thousand of a country over time."},{"type":"paragraph","text":"Looking at the graph, it can be inferred that from 1990 to 2010"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"UPSC accepts D. The birth-minus-death gap grows over part of 1990–2010 and then becomes roughly constant, rather than following one uniform trend throughout the entire interval. The final key is retained for scoring.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-63.png","sourceImageAlt":"Birth rate and death rate per thousand from 1970 to 2010."},{"id":"upsc-2018-prelims-csat-a-064","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":64,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"With reference to the above graph, consider the following statements considering 1970 as base year:\\n\\n1. Population has stabilized after 35 years.\\n2. Population growth rate has stabilized after 35 years.\\n3. Death rate has fallen by 10% in the first 10 years\\n4. Birth rate has stabilized after 35 years.\\n\\nWhich of the above are the most logical and rational statements that can be made from the above graph?","options":{"a":"1 and 2 only","b":"1, 2 and 3","c":"3 and 4","d":"2 and 4"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=31","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":31,"blocks":[{"type":"passage","text":"The graph gives the birth rate and death rate per thousand of a country over time."},{"type":"paragraph","text":"With reference to the above graph, consider the following statements considering 1970 as base year:"},{"type":"paragraph","text":"1. Population has stabilized after 35 years.\\n2. Population growth rate has stabilized after 35 years.\\n3. Death rate has fallen by 10% in the first 10 years\\n4. Birth rate has stabilized after 35 years."},{"type":"paragraph","text":"Which of the above are the most logical and rational statements that can be made from the above graph?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"After about 2005 the birth rate and the difference between birth and death rates are nearly flat. Thus 2 and 4 are supported; a constant positive growth rate does not imply a constant population.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-63.png","sourceImageAlt":"Birth rate and death rate per thousand from 1970 to 2010."},{"id":"upsc-2018-prelims-csat-a-065","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":65,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"Average hourly earnings per year (E) of the workers in a firm are represented in figures A and B as follows:\\n\\nFrom the figures, it is observed that the","options":{"a":"values of E are different","b":"ranges (i.e., the difference between the maximum and the minimum) of E are different","c":"slopes of the graphs are same","d":"rates of increase of E are different"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=33","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":33,"blocks":[{"type":"paragraph","text":"Average hourly earnings per year (E) of the workers in a firm are represented in figures A and B as follows:"},{"type":"paragraph","text":"From the figures, it is observed that the"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Both figures show earnings rising from 20 to 40 over four years, at 5 per year. Changing the vertical scale changes appearance, but not the numerical slope.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-65.png","sourceImageAlt":"Two graphs of average hourly earnings from 2013 to 2017, drawn with different vertical-axis scales."},{"id":"upsc-2018-prelims-csat-a-066","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":66,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the figures given below :\\n\\nTo fit the question mark, the correct answer is","options":{"a":"Figure (a)","b":"Figure (b)","c":"Figure (c)","d":"Figure (d)"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=33","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":33,"blocks":[{"type":"paragraph","text":"Consider the figures given below :"},{"type":"paragraph","text":"To fit the question mark, the correct answer is"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Across each row the head symbols and main shapes cycle, while the hanging elements cycle through two bent, three straight and four forked strokes. The missing element is the square-headed straight line with two bent strokes, figure A.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-66.png","sourceImageAlt":"Three by three pattern of symbols with a missing lower-right figure, and four answer figures labelled a to d."},{"id":"upsc-2018-prelims-csat-a-067","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":67,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"Consider the following figures A and B The manufacturing cost and projected sales for a product are shown in the above figures A and B respectively.\\n\\nWhat is the minimum number of pieces that should be manufactured to avoid a loss?","options":{"a":"2000","b":"2500","c":"3000","d":"3500"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=35","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":35,"blocks":[{"type":"paragraph","text":"Consider the following figures A and B The manufacturing cost and projected sales for a product are shown in the above figures A and B respectively."},{"type":"paragraph","text":"What is the minimum number of pieces that should be manufactured to avoid a loss?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"At 1000 pieces, revenue is 1000×₹400=₹4 lakh against ₹6 lakh cost. At 2000 it is 2000×₹350=₹7 lakh, equal to ₹7 lakh cost. The minimum listed break-even quantity is 2000.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-67.png","sourceImageAlt":"Graph A shows manufacturing cost in lakhs against pieces manufactured; graph B shows selling price per piece against pieces sold."},{"id":"upsc-2018-prelims-csat-a-068","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":68,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A lift has the capacity of 18 adults or 30 children. How many children can board the lift with 12 adults?","options":{"a":"6","b":"10","c":"12","d":"15"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=35","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":35,"blocks":[{"type":"paragraph","text":"A lift has the capacity of 18 adults or 30 children. How many children can board the lift with 12 adults?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Twelve adults use 12/18=2/3 of capacity, leaving 1/3. One-third of the 30-child capacity is 10 children.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-069","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":69,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A person bought a refrigerator worth Rs.22,800 with 12.5% interest compounded yearly. At the end of first year he paid Rs.8,650 and at the end of second year Rs. 9,125. How much will he have to pay at the end of third year to clear the debt?","options":{"a":"Rs. 9,990","b":"Rs. 10,000","c":"Rs. 10,590","d":"Rs.11,250"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=35","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":35,"blocks":[{"type":"paragraph","text":"A person bought a refrigerator worth Rs.22,800 with 12.5% interest compounded yearly. At the end of first year he paid Rs.8,650 and at the end of second year Rs. 9,125. How much will he have to pay at the end of third year to clear the debt?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"After year 1: 22,800×1.125−8,650=17,000. After year 2: 17,000×1.125−9,125=10,000. Year 3 adds 12.5%, so ₹11,250 clears the debt.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-070","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":70,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following figures. In figures (I) to (VI), some parts are shown to change their positions in regular directions. Following the same sequence, which of the figures given below will appear at (VII) stage?","options":{"a":"Figure (a)","b":"Figure (b)","c":"Figure (c)","d":"Figure (d)"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=35","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":35,"blocks":[{"type":"paragraph","text":"Consider the following figures. In figures (I) to (VI), some parts are shown to change their positions in regular directions. Following the same sequence, which of the figures given below will appear at (VII) stage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Track the square and triangle separately through the six sectors. Each advances one sector per step in its own direction; the seventh arrangement returns to the layout represented by figure B.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-70.png","sourceImageAlt":"Six circular arrangements of a triangle and square, followed by four candidate seventh-stage arrangements labelled a to d."},{"id":"upsc-2018-prelims-csat-a-071","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":71,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"Consider the following graphs. The curves in the graphs indicate different age groups in the populations of two countries A and B over a period of few decades :\\n\\nWith reference to the above graphs, which of the following are the most logical and rational inferences that can be made?\\n\\n1. Over the last two and a half decades, the dependency ratio for country B has decreased.\\n2. By the end of next two and a half decades, the dependency ratio of country A will be much less than that of country B.\\n3. In the next two decades, the workforce relative to its total population will increase in country B as compared to country A.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=37","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":37,"blocks":[{"type":"paragraph","text":"Consider the following graphs. The curves in the graphs indicate different age groups in the populations of two countries A and B over a period of few decades :"},{"type":"paragraph","text":"With reference to the above graphs, which of the following are the most logical and rational inferences that can be made?"},{"type":"paragraph","text":"1. Over the last two and a half decades, the dependency ratio for country B has decreased.\\n2. By the end of next two and a half decades, the dependency ratio of country A will be much less than that of country B.\\n3. In the next two decades, the workforce relative to its total population will increase in country B as compared to country A."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Country B’s working-age share has risen relative to dependants, and its workforce continues to grow more strongly than A’s. Statements 1 and 3 follow. The projected dependency ratio for A is not lower than B’s.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-71.png","sourceImageAlt":"Population curves for countries A and B: under 15, ages 15 to 64 and ages 64 and above, from 1950 to 2050."},{"id":"upsc-2018-prelims-csat-a-072","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":72,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Lakshmi, her brother, her daughter and her son are badminton players.\\nA game of doubles is about to begin :\\n\\ni. Lakshmi’s brother is directly across the net from her daughter.\\nii. Her son is diagonally across the net from the worst player’s sibling.\\niii. The best player and the worst player are on the same side of the net.\\n\\nWho is the best player?","options":{"a":"Her brother","b":"Her daughter","c":"Her son","d":"Lakshmi"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=37","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":37,"blocks":[{"type":"paragraph","text":"Lakshmi, her brother, her daughter and her son are badminton players.\\nA game of doubles is about to begin :"},{"type":"paragraph","text":"i. Lakshmi’s brother is directly across the net from her daughter.\\nii. Her son is diagonally across the net from the worst player’s sibling.\\niii. The best player and the worst player are on the same side of the net."},{"type":"paragraph","text":"Who is the best player?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The opposite and diagonal positions constrain the two sibling pairs. Whichever permitted player is worst, the best player sharing that side is Lakshmi’s brother.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-073","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":73,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"The graph given below indicates the changes in key policy rates made by Central Bank several times in a year Which one of the following can be the most likely reason for the Central Bank for such an action?","options":{"a":"Encouraging foreign investment","b":"Increasing the liquidity","c":"Encouraging both public and private savings","d":"Anti inflationary stance"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=39","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":39,"blocks":[{"type":"paragraph","text":"The graph given below indicates the changes in key policy rates made by Central Bank several times in a year Which one of the following can be the most likely reason for the Central Bank for such an action?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Rising repo and reverse repo rates tighten monetary conditions. The most likely motivation is an anti-inflationary stance.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-73.png","sourceImageAlt":"Repo rate, cash reserve ratio and reverse repo rate plotted from July 2010 to June 2011."},{"id":"upsc-2018-prelims-csat-a-074","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":74,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"With reference to the table, which of the following is/are the most logical and rational inference/inferences that can be made?\\n\\n1. Higher per capita income is generally associated with higher Tele-density.\\n2. Higher GDP growth rate always ensures higher per capita income.\\n3. Higher GDP growth rate does not necessarily ensure higher Tele-density.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"3 only"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=39","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":39,"blocks":[{"type":"paragraph","text":"The table gives the GDP growth rate and Tele-density data of different States of a country in a particular year."},{"type":"table","headers":["State","Per capita income ($)","GDP growth rate (%)","Tele-density"],"rows":[["State 1","704","9.52","70.27"],["State 2","419","5.31","35.88"],["State 3","254","10.83","50.07"],["State 4","545","9.78","5.94"],["State 5","891","10.8","76.12"],["State 6","1077","11.69","77.5"],["State 7","900","8.88","104.86"],["State 8","395","5.92","6"],["State 9","720","7.76","82.25"],["State 10","893","9.55","96.7"],["State 11","363","4.7","57.7"],["State 12","966","7.85","63.8"],["State 13","495","9.37","52.3"],["State 14","864","5.46","97.9"],["State 15","497","7.48","62.3"],["State 16","777","7.03","93.8"],["State 17","335","5.8","49.9"],["State 18","599","7.49","47.84"]]},{"type":"paragraph","text":"With reference to the table, which of the following is/are the most logical and rational inference/inferences that can be made?"},{"type":"paragraph","text":"1. Higher per capita income is generally associated with higher Tele-density.\\n2. Higher GDP growth rate always ensures higher per capita income.\\n3. Higher GDP growth rate does not necessarily ensure higher Tele-density."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"High income broadly accompanies high tele-density, but similar growth rates can coexist with very different tele-density. Statements 1 and 3 are supported; growth alone does not ensure a high income level.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-075","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":75,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"With reference to the above table, the following assumptions have been made :\\n\\n1. Nowadays, prosperity of an already high performing State cannot be sustained without making further large investments in its telecom infrastructure.\\n2. Nowadays, a very high Tele-density is the most essential condition for promoting the business and economic growth in a State.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=41","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":41,"blocks":[{"type":"paragraph","text":"The table gives the GDP growth rate and Tele-density data of different States of a country in a particular year."},{"type":"table","headers":["State","Per capita income ($)","GDP growth rate (%)","Tele-density"],"rows":[["State 1","704","9.52","70.27"],["State 2","419","5.31","35.88"],["State 3","254","10.83","50.07"],["State 4","545","9.78","5.94"],["State 5","891","10.8","76.12"],["State 6","1077","11.69","77.5"],["State 7","900","8.88","104.86"],["State 8","395","5.92","6"],["State 9","720","7.76","82.25"],["State 10","893","9.55","96.7"],["State 11","363","4.7","57.7"],["State 12","966","7.85","63.8"],["State 13","495","9.37","52.3"],["State 14","864","5.46","97.9"],["State 15","497","7.48","62.3"],["State 16","777","7.03","93.8"],["State 17","335","5.8","49.9"],["State 18","599","7.49","47.84"]]},{"type":"paragraph","text":"With reference to the above table, the following assumptions have been made :"},{"type":"paragraph","text":"1. Nowadays, prosperity of an already high performing State cannot be sustained without making further large investments in its telecom infrastructure.\\n2. Nowadays, a very high Tele-density is the most essential condition for promoting the business and economic growth in a State."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The table gives associations for one year and cannot establish that additional telecom investment or very high tele-density is an indispensable condition for future prosperity. Neither assumption follows.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-076","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":76,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"The following graph indicates the composition of our tax revenue for a period of two decades :\\n\\nWith reference to the above graph, which of the following is/are the most logical and rational inference/ inferences that can be made?\\n\\n1. During the given period, the revenue from Direct Taxes as percentage of gross tax revenue has increased while that of Indirect Taxes decreased.\\n2. The trend in the revenue from Excise Duty demonstrates that the growth of manufacturing sector has been negative during the given period.\\n\\nSelect the correct answer using the code given below,","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=41","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":41,"blocks":[{"type":"paragraph","text":"The following graph indicates the composition of our tax revenue for a period of two decades :"},{"type":"paragraph","text":"With reference to the above graph, which of the following is/are the most logical and rational inference/ inferences that can be made?"},{"type":"paragraph","text":"1. During the given period, the revenue from Direct Taxes as percentage of gross tax revenue has increased while that of Indirect Taxes decreased.\\n2. The trend in the revenue from Excise Duty demonstrates that the growth of manufacturing sector has been negative during the given period."},{"type":"paragraph","text":"Select the correct answer using the code given below,"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Corporate and personal-income tax shares increase overall while indirect-tax shares decrease. A falling excise share does not itself prove negative manufacturing growth. Only 1 follows.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-76.png","sourceImageAlt":"Shares of gross tax revenue from excise, customs, corporate tax, personal income tax and service tax, 1990–91 to 2011–12."},{"id":"upsc-2018-prelims-csat-a-077","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":77,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If x – y = 8, then which of the following must be true?\\n\\n1. Both x and y must be positive for any value of x and y.\\n2. If x is positive, y must be negative for any value of x and y.\\n3. If x is negative, y must be positive for any value of x and y.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2 nor 3"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=41","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":41,"blocks":[{"type":"paragraph","text":"If x – y = 8, then which of the following must be true?"},{"type":"paragraph","text":"1. Both x and y must be positive for any value of x and y.\\n2. If x is positive, y must be negative for any value of x and y.\\n3. If x is negative, y must be positive for any value of x and y."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"x−y=8 permits both negative (−1,−9) or both positive (10,2), so neither of the first two claims must hold. With negative x, y=x−8 is also negative, contradicting claim 3.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-078","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":78,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the most rational and crucial message given by the passage?","options":{"a":"Mass production of meat through industrial farming is cheap and is suitable for providing protein nutrition to poor countries.","b":"Meat-producing industry violates the laws against cruelty to animals.","c":"Mass production of meat through industrial farming is undesirable and should be stopped immediately.","d":"Environmental cost of meat production is unsustainable when it is produced through industrial farming."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=43","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":43,"blocks":[{"type":"passage","text":"The quest for cheap and plentiful meat has resulted in factory farms where more and more animals are squeezed into smaller lots in cruel and shocking conditions. Such practices have resulted in many of the world’s health pandemics such as the avian flu. Worldwide, livestock are increasingly raised in cruel, cramped conditions, where animals spend their short lives under artificial light, pumped full of antibiotics and growth hormones, until the day they are slaughtered. Meat production is water-intensive. 15000 litres of water is needed for every kilogram of meat compared with 3400 litres for rice, 3300 litres for eggs and 255 litres for a kilogram of potatoes."},{"type":"paragraph","text":"What is the most rational and crucial message given by the passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage describes disease, resource use and intensive water requirements as costs of industrial meat production. Its supported message concerns environmental unsustainability.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-079","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":79,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most rational and crucial message given by the passage?","options":{"a":"The conflict between man and wildlife cannot be resolved, no matter what efforts we make.","b":"Safe wildlife corridors between protected areas is an essential aspect of conservation efforts.","c":"India needs to declare more protected areas and set up more tiger reserves.","d":"India’s National Parks and Tiger Reserves need to be professionally managed."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=43","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":43,"blocks":[{"type":"passage","text":"A male tiger was removed from Pench Tiger Reserve and was relocated in Panna National Park. Later, this tiger trekked toward his home 250 miles away. The trek of this solitary tiger highlights a crisis. Many wildlife reserves exist as islands of fragile habitat in a vast sea of humanity, yet tigers can range over a hundred miles, seeking prey, mates and territory. Nearly a third of India’s tigers live outside tiger reserves, a situation that is dangerous for both human and animal. Prey and tigers can only disperse if there are recognized corridors of land between protected areas to allow unmolested passage."},{"type":"paragraph","text":"Which of the following is the most rational and crucial message given by the passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The returning tiger illustrates the need for safe dispersal routes between habitat islands. Protected areas require connecting wildlife corridors.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-080","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":80,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made :\\n\\n1. The strategy of conservation of wildlife by relocating them from one protected area to another is not often successful.\\n2. India does not have suitable legislation to save the tigers, and its conservation efforts have failed which forced the tigers to live outside protected areas.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=43","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":43,"blocks":[{"type":"passage","text":"A male tiger was removed from Pench Tiger Reserve and was relocated in Panna National Park. Later, this tiger trekked toward his home 250 miles away. The trek of this solitary tiger highlights a crisis. Many wildlife reserves exist as islands of fragile habitat in a vast sea of humanity, yet tigers can range over a hundred miles, seeking prey, mates and territory. Nearly a third of India’s tigers live outside tiger reserves, a situation that is dangerous for both human and animal. Prey and tigers can only disperse if there are recognized corridors of land between protected areas to allow unmolested passage."},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. The strategy of conservation of wildlife by relocating them from one protected area to another is not often successful.\\n2. India does not have suitable legislation to save the tigers, and its conservation efforts have failed which forced the tigers to live outside protected areas."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The relocated tiger’s attempted return supports the limited assumption that relocation is not always successful. The passage does not attribute tigers outside reserves to unsuitable legislation or failure of all conservation efforts.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}}]');export{e as p};
